fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\Sym4D_cutsAndFits';
if ~exist('fit_resEi200','var')
    %fit_data_file = 'FitEn_cut200_1Dsbg_dirGH_dE20_fix_bg_slope.mat'; % fit 1D background with no Q-slope
    %fit_data_file = 'FitEn_cut200_1D_fit_bg_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    fit_data_file = 'FitEn_cut200ref110_2D_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    ld = load(fullfile(fit_data_path,fit_data_file));
    if isfield(ld,'fit_resEi200')
        fit_resEi200 = ld.fit_resEi200;
    else
        fit_resEi200 = ld.fit_res;
    end
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_file = 'multicuts_fit_dataGH_ei200meV.mat';
if ~exist('cuts2fit200','var')
    ld = load(fullfile(data_path,fit_file));
    cuts2fit200 = ld.cuts2fit200;
end
cuts2fit = cuts2fit200;
fit_res = fit_resEi200;
mi = maps_instrument(200,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = {cuts2fit200.cut110_sel};
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end
cuts2fit200.cut110_sel = cl{1};
the2Dcuts = {cut(cuts2fit.cut110_sel,[0,0.02,2],[])}; %[output:96cfd0d9]
%%
[Sgnl,J0,G] = plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0,1.5],[20,60],[0,100]}); %[output:3ee259e0] %[output:4ebf321c] %[output:0daeb1df]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1));
e_min = Sgnl.x(1);

%%
En = 90 %[output:5f7182b4]
dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
%the2Dcuts = cuts2fit.cutsS_list;%(1:2);
%the2Dcuts = {cut(cuts2fit.cut110_sel,[0,0.02,2],[])};%(1:2);

%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
lfit_par = fit_res.all_fit_par(en_idx);
en_range = lfit_par.en_range;
[fit_obj,fit_par,figa,figb]=refit_singleset_peaks(the2Dcuts,en_range,lfit_par,0.2,true,false); %[output:3b04bf54] %[output:7ccae051] %[output:747c6b8b] %[output:04f3de40] %[output:52bf09f5]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
%fit_res.all_fit_par(en_idx).p = fit_par.p;
Sgnl.signal(en_idx) = fit_par.p(4);
J0.signal(en_idx) = fit_par.p(6);
G.signal(en_idx) = fit_par.p(3);
plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0,1.5],[20,60],[0,100]},{Sgnl,J0,G}); %[output:7e84d8a7] %[output:4be1a9d8] %[output:106e91cc]

%%
[fit_res,Sg,J0,G] = refit_data_around_peaks(the2Dcuts,fit_res,0.2,true); %[output:5c5e996b] %[output:573a1a91] %[output:033c5352] %[output:2f530c80] %[output:2e20179e] %[output:33bed789] %[output:50476055] %[output:5e122624] %[output:01d5ec1f] %[output:0feaf34c] %[output:2cd0a71b] %[output:810a9317] %[output:7cbf5a5d] %[output:8861c285] %[output:538ad183] %[output:224945e5] %[output:72591358] %[output:2d7bf348] %[output:19c8ba0e] %[output:18266552] %[output:5865588b] %[output:34d3ba57] %[output:910d4a50] %[output:121bfebc] %[output:59008a1d] %[output:1f8f023c] %[output:49d1287d] %[output:0baaba4d] %[output:6bdade79] %[output:7395697f] %[output:718788e5] %[output:70fd419d] %[output:7faa66d0] %[output:340efd29] %[output:75e772f5] %[output:18b06ce6] %[output:7aa28098] %[output:0a305f21] %[output:4f3217b4] %[output:19ec28ca] %[output:87b790b2] %[output:0fb7144f] %[output:219a1fa6]
%%
plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0,1.5],[20,60],[0,100]},{Sg,J0,G});
%[output:7e8497fa] %[output:12783b5e] %[output:6c7cf030]
%%

%%
fit_res.Speak_varsl = Sg;
fit_res.J0peak_varsl = J0;
fit_res.gamma_peak_varsl = G;

% fit_res.Speak = Sg;
% fit_res.J0peak = J0;
% fit_res.gamma_peak = G;

fit_res.peak_fit_par = [peak_fit_par{:}];
fit_res.peak_fit_VarSlope_par = fit_res.peak_fit_par;
fit_resEi200 = fit_res;
save(fullfile(fit_data_path,fit_data_file),"fit_resEi200");

